/**
 * Local data source: reads content/seed.json (generated by `npm run seed:legacy`).
 * Used when NEXT_PUBLIC_SUPABASE_URL / NEXT_PUBLIC_SUPABASE_ANON_KEY are not set.
 * Returns the same shapes as data-supabase.ts (published / visible content only).
 */
import { promises as fs } from "node:fs";
import path from "node:path";
import { SeedFile, type Media, type Post, type PostType, type Section, type SiteSettings } from "./schema";

let cache: Promise<SeedFile> | null = null;

function loadSeed(): Promise<SeedFile> {
  // In dev, re-read on every call so a re-run of the seed script shows up without a restart.
  if (cache && process.env.NODE_ENV === "production") return cache;
  const load = async () => {
    const file = path.join(process.cwd(), "content", "seed.json");
    const raw = await fs.readFile(file, "utf8");
    return SeedFile.parse(JSON.parse(raw));
  };
  cache = load();
  return cache;
}

export async function getSettings(): Promise<SiteSettings> {
  return (await loadSeed()).settings;
}

export async function getSections(): Promise<Section[]> {
  const { sections } = await loadSeed();
  return sections.filter((s) => s.visible).sort((a, b) => a.sortOrder - b.sortOrder);
}

export async function getPosts(type: PostType): Promise<Post[]> {
  const { posts } = await loadSeed();
  return posts.filter((p) => p.type === type && p.status === "published").sort((a, b) => a.sortOrder - b.sortOrder);
}

export async function getPost(type: PostType, slug: string): Promise<Post | null> {
  return (await getPosts(type)).find((p) => p.slug === slug) ?? null;
}

export async function getMediaList(): Promise<Media[]> {
  return (await loadSeed()).media;
}
